import {readFile, writeFile} from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const catalogs = {};
for (const language of ['en', 'zh-Hans', 'ja', 'ru'])
  catalogs[language] = JSON.parse(await readFile(new URL(`src/SamaLcd.Core/Localization/${language}.json`, root), 'utf8'));
await writeFile(new URL('src/SamaLcd/wwwroot/locales.js', root),
  '// Generated by scripts/generate-locales.mjs from the shared JSON catalogs.\n' +
  'globalThis.SamaLcdCatalogs = ' + JSON.stringify(catalogs, null, 2) + ';\n');
